export const meshForGeometryAndImage = (
  geometry: Geometry,
  imageUrl: string,
  renderer: Renderer
): Mesh => {
  const lineMaterial = new THREE.LineBasicMaterial({
    color: 0x666666,
    linewidth: 1,
    linecap: "round", //ignored by WebGLRenderer
    linejoin: "round", //ignored by WebGLRenderer
  })

  const mesh = new THREE.Mesh(geometry, lineMaterial)
  mesh.onBeforeRender = function() {
    if (!this.hasRendered) {
      var texture = new THREE.TextureLoader().load(imageUrl)
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy()

      var material = new THREE.MeshBasicMaterial({
        map: texture,
      })

      this.material = material
      this.hasRendered = true
    }
  }
  return mesh
}

export const projectVectorOntoTorus = (vec: Point2D): Vector3 => {
  const major = R + r * Math.cos(vec.y)
  return new THREE.Vector3(
    major * Math.cos(vec.x),
    r * Math.sin(vec.y),
    major * Math.sin(vec.x)
  )
}
